head.script:

		scwin.onpageload = function() {
			var json = [
				{
					col1:'Name1',
					col2:'Value1',
					col3:'Option1'
				},
				{
					col1:'Name2',
					col2:'Value2',
					col3:'Option2'
				},
				{
					col1:'Name3',
					col2:'Value3',
					col3:'Option3'
				}
			];
			dataList1.setJSON( json );
		};

		scwin.onpageunload = function() {

		};

		// SystemMenu
		// - ColumnHide : 선택 컬럼 숨기기
		// - ColumnShowAll : 전체 컬럼 숨기기 해제
		// - ColumnFix : 선택 컬럼 틀고정
		// - ColumnUnfixAll : 전체 컬럼 틀고정 취소
		// - ColumnAdjustWidth : 선택 컬럼 크기 자동 맞추기
		// - ColumnAdjustAuto : 전체 컬럼 크기 자동 맞추기
		// - FoldAll : 전체 그룹 접기
		// - UnfoldAll : 전체 그룹 펼치기
		// - Group : 전체 그룹 해제
		// - Ungroup : 선택 컬럼 그룹 해제
		// - UngroupAll : 선택 컬럼 그룹

		// 컨텍스트 메뉴를 열기 전에 호출되어, 컨텍스트 메뉴를 구성할 수있게 합니다.
		// result
		// - false : 컴텍스트 메뉴가 열리지 않습니다.
		// - hideSystemMenu
		scwin.gridView1_oncontextopen = function(row,col) {
			// return false; // 컨텍스트 메뉴를 보여주지 않습니다.
			// return { hideSystemMenu: false } // 전체 시스템 메뉴를 보여주지 않습니다.
			return {
				hideSystemMenu: [ "ColumnHide" ], // 특정 항목의 시스템 메뉴를 보여주지 않습니다.
				appendMenu: [{
					label:"특별한 컬럼 숨기기",
					// 사용자 메뉴의 표시 문자열
					userMenuId:"userColumnHide",
					// 사용자 메뉴의 id, 해당 컨텍스트 메뉴가 클릭될때, 입력값으로 전달됨
					className:""
					// 사용자 메뉴의 스타일 클래스 이름 
				}], // 시스템 메뉴 아래에, 사용자 메뉴를 추가합니다.
			};
		};

		// 컨텍스트 메뉴가 클릭 된 후 호출됩니다. 시스템 메뉴는 시스템 기능이 완료된 후 호출됩니다.
		scwin.gridView1_oncontextclick = function(row,col,userMenuId,isSystemMenu,systemMenu) {
			if(isSystemMenu){
				console.log(systemMenu + " clicked at (" + col + "," + row + ")!");
			} else {
				console.log(userMenuId + " clicked at (" + col + "," + row + ")!");
			}
		};

		scwin.trigger2_onclick = function() {
			var focusedCell = gridView1.getLastFocusedCell();
            gridView1._setFocusedCell(focusedCell.focusedRowIndex, focusedCell.focusedColIndex);
            focusedCell.focusedTd.focus();
		}


	scwin.fireClick = function(node){            
		if( document.createEventObject ) {
			node.fireEvent('oncontextmenu') ;  
		} else if( document.createEvent ) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('contextmenu', true, false);
			node.dispatchEvent(evt);    
		} else if (typeof node.contextmenu == 'function' ) {
			node.oncontextmenu();  
		}
	}
	scwin.rightClick = function(id){
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireClick(el);
	}         
	scwin.checkVal = function(){
		let element = WebSquare.wUnit.getDomById('gridView2_contextMenu_list')
		let check_class = element.querySelector('li').classList.contains('w2list_listRow_over');
		return check_class;
	}   
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "scwin.rightClick('gridView2_cell_0_2')");
		WebSquare.wUnit.addCommand("pause", "1000");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
